"""Screen BLAS preferences without changing inference precision or shapes."""
import os,sys,pathlib,json,statistics,importlib
import torch
from fireprot.adapters.atlasfold.runtime import triangle_attention,triangle_multiplication
from benchmarks.atlasfold.profile_inference import resolve_physical_device,_GpuProcessMonitor
from atlasfold.model.network.primitives.triangle_update import TriangleAttentionStartingNode,TriangleAttentionEndingNode,TriangleMultiplicationOutgoing,TriangleMultiplicationIncoming
sys.path.insert(0,'/media/IntelSSD/fireprot/runtime/torch_extensions/fireprot_pair_fusions_861dc90206f7b9a5')
ext=importlib.import_module('fireprot_pair_fusions_861dc90206f7b9a5')
torch.set_num_threads(8);torch.manual_seed(1151);torch.cuda.init()
device=resolve_physical_device();monitor=_GpuProcessMonitor(device['gpu'],os.getpid(),1);monitor.start()
report={'device':device,'initial_preference':str(torch.backends.cuda.preferred_blas_library()),'records':[]}
def bench(fn):
 values=[]
 for i in range(4):
  a=torch.cuda.Event(enable_timing=True);b=torch.cuda.Event(enable_timing=True);a.record();y=fn();b.record();b.synchronize()
  if i:values.append(a.elapsed_time(b))
 return y,statistics.median(values)
try:
 state=torch.load('/media/PM982/engramfold/folding_e2e_20260921/weights/atlasfold/snapshot/weights/atlasfold-260703.pth',map_location='cpu',weights_only=True,mmap=True)
 with torch.inference_mode(),torch.autocast('cuda',dtype=torch.bfloat16):
  for n,validn in ((1024,1000),(1536,1536)):
   for cls,label in ((TriangleAttentionStartingNode,'tri_attn_start'),(TriangleAttentionEndingNode,'tri_attn_end'),(TriangleMultiplicationOutgoing,'tri_mul_out'),(TriangleMultiplicationIncoming,'tri_mul_in')):
    attention=label.startswith('tri_attn');m=(cls(128,4) if attention else cls(128)).eval().cuda().bfloat16();prefix='main_stack.blocks.0.'+label+'.'
    m.load_state_dict({k[len(prefix):]:v for k,v in state.items() if k.startswith(prefix)},strict=True)
    x=torch.randn(1,n,n,128,device='cuda',dtype=torch.bfloat16);v=torch.arange(n,device='cuda')<validn;mask=v[None,:,None]&v[None,None,:]
    fn=(lambda:triangle_attention(m,x,mask,ending=label=='tri_attn_end',extension=ext,valid_length=validn,fuse_softmax=True)) if attention else (lambda:triangle_multiplication(m,x,mask,outgoing=label=='tri_mul_out',extension=ext))
    torch.backends.cuda.preferred_blas_library('hipblas');ref,t0=bench(fn)
    for policy in ('hipblaslt','ck'):
     record={'length':n,'module':label,'requested_policy':policy,'reference_ms':t0}
     try:
      torch.cuda.synchronize();torch.backends.cuda.preferred_blas_library(policy)
      y,t1=bench(fn);record.update(effective_preference=str(torch.backends.cuda.preferred_blas_library()),candidate_ms=t1,equal=torch.equal(y,ref),max_abs_delta=(y.float()-ref.float()).abs().max().item());del y
     except RuntimeError as error:record['error']=str(error)
     report['records'].append(record);print(json.dumps(record),flush=True)
    torch.backends.cuda.preferred_blas_library('hipblas');del ref,x,mask,m
finally:
 report['isolation']=monitor.stop()
 pathlib.Path('/media/IntelSSD/fireprot/outputs/atlasfold/blas-preference-probe.json').write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps(report),flush=True)

