"""Matched wrapper imports and extension priming on both sides of a layout trial."""
import hashlib,json,os,pathlib,subprocess,statistics
import numpy as np
root=pathlib.Path('/media/IntelSSD/fireprot');snapshot=root/'runtime/atlasfold_ab_0f15349'
out=root/'outputs/atlasfold/repeat-norm-layout-0f15349';assert not out.exists();out.mkdir()
hashes=json.loads((snapshot/'source-manifest.json').read_text())
trial=pathlib.Path('/tmp/fireprot_atlas_norm_layout_ab_model.py');kernel=pathlib.Path('/tmp/fireprot_atlas_norm_layout_probe.cu')
trial_hashes={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in (trial,kernel)}
report={'status':'running','controller_pid':os.getpid(),'snapshot':str(snapshot),'trial_hashes':trial_hashes,'pairs':[],'seed':102,'length':1536,'protocol':'Both sides import the same wrapper and extension before request timing; fresh model per process; stage events off.'}
def save(): (out/'summary.json').write_text(json.dumps(report,indent=2)+'\n')
def verify():
 for name,h in hashes.items():assert hashlib.sha256((snapshot/name).read_bytes()).hexdigest()==h,name
 for name,h in trial_hashes.items():assert hashlib.sha256(pathlib.Path(name).read_bytes()).hexdigest()==h,name
python='/media/PM982/engramfold/folding_e2e_20260921/venvs/atlasfold-rocm/bin/python'
try:
 verify();save()
 for pair in range(3):
  records={}
  for label in (('baseline','candidate') if pair%2==0 else ('candidate','baseline')):
   verify();dest=out/f'pair{pair}-{label}'
   env=dict(os.environ,PYTHONPATH=str(snapshot),FIREPROT_EXTENSION_CACHE=str(root/'runtime/torch_extensions'),FIREPROT_NORM_LAYOUT_TRIAL='1' if label=='candidate' else '0')
   cmd=[python,str(trial),'--input',str(root/'benchmarks/protenix/inputs/umem_L01536_6b140cc19f02d9b9.json'),'--out',str(dest),'--backend','hip-fused','--allow-long1536','--seed','102','--repeats','1','--stage-events','off']
   report['active']={'pair':pair,'label':label};save()
   with (out/f'pair{pair}-{label}.log').open('w') as log:subprocess.run(cmd,cwd=snapshot,env=env,stdout=log,stderr=subprocess.STDOUT,check=True)
   m=json.loads((dest/'manifest.json').read_text());assert m['status']=='complete' and m['isolation']['passed']
   assert m['experimental_candidate']['counts']['transpose_cast']==(264 if label=='candidate' else 0)
   assert m['fireprot']['counts']['fused_attention']==528 and m['fireprot']['counts']['hip_multiplication']==528
   records[label]={'request_seconds':m['first_request_seconds'],'prediction_seconds':m['records'][0]['prediction_wall_seconds'],'device':m['device'],'manifest':str(dest/'manifest.json')}
  a=np.load(out/f'pair{pair}-baseline/repeat0-seed102-sample0.npz');b=np.load(out/f'pair{pair}-candidate/repeat0-seed102-sample0.npz')
  comparison={k:a[k].shape==b[k].shape and a[k].dtype==b[k].dtype and a[k].tobytes()==b[k].tobytes() for k in a.files}
  assert set(a.files)==set(b.files) and all(comparison.values()) and records['baseline']['device']==records['candidate']['device']
  report['pairs'].append({'pair':pair,'records':records,'raw_bytes_equal':comparison,'request_speedup':records['baseline']['request_seconds']/records['candidate']['request_seconds']});save();print(json.dumps(report['pairs'][-1]),flush=True)
 report['medians']={label:statistics.median(p['records'][label]['request_seconds'] for p in report['pairs']) for label in ('baseline','candidate')}
 report['median_request_speedup']=report['medians']['baseline']/report['medians']['candidate'];report['status']='complete';report.pop('active',None);save()
except BaseException as error:
 report['status']='failed';report['error']=repr(error);save();raise
